shader:
uniform sampler2D flow;uniform float moving;
vec4 cell(vec2 uv){
  vec3 f=moving>0.5?(texture2D(flow,uv).rgb-vec3(0.5,0.5,0.0))*vec3(0.36,0.36,0.8):vec3(0.0);
  float time=u_time;
  float px=(uv.x-0.5-f.x)*u_aspect, py=uv.y-0.5-f.y;
  float qx=px+0.22*sin(py*5.2+time*0.17)+0.15*sin(px*2.4-py*3.1-time*0.1);
  float qy=py+0.19*sin(px*3.5+time*0.13);
  float radius=length(vec2(qx*0.8+0.18,qy*1.1));
  float folds=0.5+0.5*sin(radius*14.0-qx*2.8+sin(qy*5.0)*1.4-time*0.24);
  float cloud=0.5+0.5*sin(qx*3.6-qy*2.9+time*0.09);
  float light=clamp(folds*folds*(0.48+cloud*0.32)-0.075+f.z*0.75,0.0,1.0);
  float value=floor(light*255.0+0.5);
  float r=value<10.0?0.0:min(255.0,value*1.45), g=r*185.0/232.0;
  return vec4(r/255.0,g/255.0,0.0,floor(0.299*r+0.587*g)/255.0);
}
